  "source": "def summarize_values(values):
    n = len(values)
    if n == 0:
        return 0
    contrib = []
    for i in range(n):
        x = values[i]
        p = x + x * x + x * x * x
        prev = values[i - 1] if i > 0 else 0
        total_prev = sum(values[:i])
        contrib.append(p + 2 * x * prev + 2 * x * total_prev)
    for _ in range(4):
        running = 0
        new_contrib = []
        for v in contrib:
            running += v
            new_contrib.append(running)
        contrib = new_contrib
    return contrib[-1]

def readout(summary):
    return summary

def investigate(context, acquire):
    return readout(summarize_values(context["values"]))
